    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==3]
    out=[[0]*w for _ in range(h)]
    for r,c in pts:
        # each marker makes a directional comb, opening to the marker and extending away
        # Rows/cols of pattern: upper region has top 5 bar, vertical 2 posts, 3 at center;
        # lower region has 5 bar, side posts, then 8 horizontal bar.
        # Orientation inferred from examples: pattern center at marker; 5-side upward, 8-side downward.
        # widths 5, overall span 7; anchor center at marker.
        for dc in range(-2,3):
            if 0<=r-2<h and 0<=c+dc<w: out[r-2][c+dc]=5
        for rr in range(r-1,r+3):
            if 0<=rr<h:
                for dc in (-2,2):
                    if 0<=c+dc<w: out[rr][c+dc]=2
        out[r][c]=3
        for dc in range(-2,3):
            if 0<=r+3<h and 0<=c+dc<w: out[r+3][c+dc]=8
        # longitudinal horizontal stripes connect across the grid at marker's lower boundary
        if 0<=r+2<h:
            for cc in range(w): out[r+2][cc]=2
        # recolor local bottom bar region: 8 central segment and 2 remainder
        if 0<=r+2<h:
            for cc in range(w): out[r+2][cc]=8 if c-2<=cc<=c+2 else 2
    return out
